-- Node: tm-presentation (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"Clinical Presentation & Localization","body":"**Recent diving or rapid ascent?** New myelopathy may represent [spinal decompression illness](#/tree/decompression-sickness). Start high-concentration oxygen and contact hyperbaric/diving medicine immediately. Do not delay indicated recompression for routine spinal MRI. Suspected traumatic or compressive pathology still requires urgent targeted evaluation in parallel. [16]\n\n**Map the deficit:**\n- **Sensory level** — test pinprick/temperature ascending up the trunk until it normalizes; that dermatome localizes the lesion (thoracic most common).\n- **Weakness** — bilateral, often initially flaccid (spinal shock) then spastic with hyperreflexia + Babinski over days.\n- **Bladder/bowel** — urinary retention or incontinence; **always check a post-void residual.**\n- **Back pain** at the level in ~one third.\n\n**What pushes you toward URGENT structural cause (get MRI now):**\n- Severe focal back pain, fever, immunosuppression, IVDU → epidural **abscess**\n- Anticoagulation, recent procedure → epidural **hematoma**\n- Known cancer, weight loss → **metastatic compression**\n- Saddle anesthesia + retention + areflexia → **cauda equina**\n\nEvery one of these is a neurosurgical clock. The next step is the same for all: image the cord.","citation":[1,2,13,16],"options":[{"label":"Bilateral weakness + sensory level ± retention","description":"Classic acute myelopathy picture","next":"tm-mri-gate","urgency":"critical"},{"label":"Red flags for compression (fever/IVDU, anticoag, known cancer, saddle)","description":"Possible abscess / hematoma / mets / cauda equina","next":"tm-mri-gate","urgency":"critical"}],"summary":"Establish sensory level + post-void residual. Recent diving: consider spinal DCI without MRI delay; compression red flags → urgent MRI.","safetyLevel":"critical"}'::jsonb
WHERE id = 'tm-presentation' AND tree_id = 'transverse-myelitis';

-- Node: tm-mri-gate (4 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"MRI Gate: Check Diving Exception First","body":"**Recent diving or rapid ascent?** New myelopathy may represent [spinal decompression illness](#/tree/decompression-sickness). Start high-concentration oxygen and contact hyperbaric/diving medicine immediately. Do not delay indicated recompression for routine spinal MRI. Suspected traumatic or compressive pathology still requires urgent targeted evaluation in parallel. [16]\n\n**For suspected inflammatory or compressive myelopathy after considering the diving exception:** Transverse myelitis is a diagnosis of exclusion — you cannot call cord dysfunction \"inflammatory\" until you have ruled out a surgically correctable compressive lesion.\n\n**Order: MRI of the spinal cord, WITH and WITHOUT gadolinium.**\n- Image the clinically suspected level **plus the whole cord** — multifocal disease and skip lesions are common, and a cervical lesion can present with a thoracic-feeling level.\n- If MRI is unavailable, CT myelography is the fallback to exclude compression.\n- Do NOT delay imaging for the LP. Compression first.\n\n**What you are hunting:** epidural abscess, hematoma, tumor/metastasis, herniated disc, or severe stenosis pressing on the cord.","citation":[1,2,3,13,16],"options":[{"label":"COMPRESSION found (abscess / hematoma / tumor / disc)","description":"Neurosurgical emergency — NOT transverse myelitis","next":"tm-compression","urgency":"critical"},{"label":"No compression — intrinsic cord T2 signal (or normal early)","description":"Proceed with inflammatory myelopathy workup","next":"tm-workup"}],"images":[{"src":"data:image/svg+xml;utf8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%20440%20240%22%20font-family%3D%22sans-serif%22%3E%3Crect%20width%3D%22440%22%20height%3D%22240%22%20fill%3D%22%230f172a%22%2F%3E%3Ctext%20x%3D%22220%22%20y%3D%2224%22%20fill%3D%22%23e2e8f0%22%20font-size%3D%2215%22%20font-weight%3D%22bold%22%20text-anchor%3D%22middle%22%3EMRI%20cord%3A%20compressive%20vs.%20intrinsic%3C%2Ftext%3E%3Ctext%20x%3D%22110%22%20y%3D%2252%22%20fill%3D%22%23f87171%22%20font-size%3D%2212%22%20font-weight%3D%22bold%22%20text-anchor%3D%22middle%22%3ECOMPRESSIVE%20(surgical)%3C%2Ftext%3E%3Crect%20x%3D%2270%22%20y%3D%2260%22%20width%3D%2280%22%20height%3D%22150%22%20rx%3D%2210%22%20fill%3D%22%231e293b%22%20stroke%3D%22%2364748b%22%2F%3E%3Cellipse%20cx%3D%22110%22%20cy%3D%22135%22%20rx%3D%2216%22%20ry%3D%2240%22%20fill%3D%22%23334155%22%20stroke%3D%22%2394a3b8%22%2F%3E%3Cpath%20d%3D%22M70%20120%20q20%2015%2038%200%22%20fill%3D%22%23ef4444%22%20opacity%3D%220.8%22%2F%3E%3Ctext%20x%3D%22110%22%20y%3D%22118%22%20fill%3D%22%23fca5a5%22%20font-size%3D%229%22%20text-anchor%3D%22middle%22%3Emass%2Fabscess%3C%2Ftext%3E%3Ctext%20x%3D%22110%22%20y%3D%22225%22%20fill%3D%22%2394a3b8%22%20font-size%3D%229%22%20text-anchor%3D%22middle%22%3Ecord%20pushed%2Fdisplaced%3C%2Ftext%3E%3Ctext%20x%3D%22330%22%20y%3D%2252%22%20fill%3D%22%2334d399%22%20font-size%3D%2212%22%20font-weight%3D%22bold%22%20text-anchor%3D%22middle%22%3EINTRINSIC%20(inflammatory)%3C%2Ftext%3E%3Crect%20x%3D%22290%22%20y%3D%2260%22%20width%3D%2280%22%20height%3D%22150%22%20rx%3D%2210%22%20fill%3D%22%231e293b%22%20stroke%3D%22%2364748b%22%2F%3E%3Cellipse%20cx%3D%22330%22%20cy%3D%22135%22%20rx%3D%2216%22%20ry%3D%2240%22%20fill%3D%22%23334155%22%20stroke%3D%22%2394a3b8%22%2F%3E%3Cellipse%20cx%3D%22330%22%20cy%3D%22135%22%20rx%3D%228%22%20ry%3D%2226%22%20fill%3D%22%23fbbf24%22%20opacity%3D%220.85%22%2F%3E%3Ctext%20x%3D%22330%22%20y%3D%22225%22%20fill%3D%22%2394a3b8%22%20font-size%3D%229%22%20text-anchor%3D%22middle%22%3ET2%20signal%20WITHIN%20cord%3C%2Ftext%3E%3C%2Fsvg%3E","alt":"Side-by-side schematic: compressive lesion displacing the cord versus intrinsic T2 signal within the cord.","caption":"Compression displaces the cord (surgical); intrinsic inflammation shows signal within the cord (medical). MRI distinguishes them. (Original schematic.)"}],"summary":"Diving-related spinal DCI: urgent hyperbaric pathway; otherwise MRI whole cord with + without gad BEFORE LP. Compression = surgery; intrinsic signal = inflammatory workup.","safetyLevel":"critical"}'::jsonb
WHERE id = 'tm-mri-gate' AND tree_id = 'transverse-myelitis';

